// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategoryimport com.roshan.persona.system.executor.SystemOperationClassifier/** * NOUS — System Operation Handler (Module 10 v2 — upgraded interface). * * Each Android hardware domain (torch, volume, brightness, wifi, etc.) has * its own handler implementing this interface. The [com.roshan.persona.system.executor.SystemOperationExecutorImpl] * routes operations to handlers via `when(operation)` dispatch. * * ## v2 upgrades (per strategy §"Handler Interface Upgrade") * * v1 had only `execute()` — fire-and-forget. v2 adds 4 methods to address * Review 2's brutal analysis: * *  1. **[capturePreState]** — snapshot current device state BEFORE execution *     (e.g., `previousBrightness = 45%`). Used by: *      - [com.roshan.persona.system.executor.AtomicBatchCoordinator] for rollback *      - [com.roshan.persona.system.undo.PersistentUndoStack] for undo * *     Why pre-state, not inverse? (Review 2 Fix A): If user manually changes *     state after NOUS's action, "undo = inverse" causes wrong state. Pre-state *     restore always brings back the actual previous value. * *  2. **[restorePreState]** — restore a previously captured pre-state. * *  3. **[getCurrentState]** — read current device state (for idempotent check). * *  4. **[isAlreadyInTargetState]** — zero-flicker optimization (Review 2 Elite 1). *     If brightness is already at 80%, don't write 80% again — skip the *     hardware call entirely. Saves battery + avoids screen flicker. * *  5. **[resourceCategory]** — declares which [ResourceCategory] this handler *     uses, so the [AtomicBatchCoordinator] can decide parallel vs sequential *     dispatch. * * ## Exception Handling (Review 2 Fix C) * * Implementations MUST wrap every Android hardware API call in try-catch and * map exceptions to [Result.Failure] with appropriate [com.roshan.persona.common.AppError.Hardware] * subtype. Use [com.roshan.persona.system.util.HardwareExceptionMapper] for * consistent mapping. * * ## Testability * * The handler takes its Android service (CameraManager, AudioManager, etc.) * as a constructor parameter — tests inject a mock via MockK. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Architecture — Handler Interface Upgrade</a> */interface SystemOperationHandler<T : SystemOperation> {    // ─── Identity ──────────────────────────────────────────────────────────    /** Unique handler ID (e.g., "torch", "volume", "wifi"). */    val id: String    /** Human-readable name shown in debug logs + Settings → Diagnostics. */    val displayName: String    // ─── Capabilities ──────────────────────────────────────────────────────    /** Whether this handler can run on the current device (hardware/API level). */    fun isAvailable(): Boolean    /** Android permissions required to execute. */    val requiredPermissions: Set<String>    /** Resource category — used for parallel/sequential dispatch decision. */    val resourceCategory: ResourceCategory    // ─── Execution ─────────────────────────────────────────────────────────    /**     * Execute the operation.     *     * Implementations MUST:     *  1. Check [isAlreadyInTargetState] — skip if already at target (idempotent).     *  2. Call [capturePreState] for undo/rollback support.     *  3. Wrap the Android API call in try-catch.     *  4. Return [Result.Failure] with [AppError.Hardware.*] on exception.     *     * @param operation the operation to execute (with parameters).     * @return [Result.Success] or [Result.Failure].     */    suspend fun execute(operation: T): Result<Unit>    // ─── Pre-state capture (Review 2 Fix A — undo + rollback) ──────────────    /**     * Capture the current device state BEFORE executing [operation].     *     * Returned value is opaque — the executor stores it and passes it back     * to [restorePreState] on undo/rollback. Implementations decide what     * "state" means for their domain (e.g., `Int` brightness level,     * `Boolean` torch on/off, `AudioStream + Int` volume level).     *     * @return the captured pre-state, or null if state capture isn't relevant     *         for this operation (e.g., clipboard copy — no prior state).     */    suspend fun capturePreState(operation: T): Any?    /**     * Restore a previously captured pre-state.     *     * Called by:     *  - [com.roshan.persona.system.undo.PersistentUndoStack] when user says "NOUS, undo that".     *  - [com.roshan.persona.system.executor.AtomicBatchCoordinator] on batch failure.     *     * @param operation the original operation that was executed.     * @param preState  the state captured by [capturePreState] before execution.     */    suspend fun restorePreState(operation: T, preState: Any?)    // ─── Idempotent check (Review 2 Elite 1 — zero-flicker) ────────────────    /**     * Read the current device state for this operation's domain.     *     * Used by [isAlreadyInTargetState] to decide whether to skip execution.     * Returns `null` if the current state can't be read (handler should     * proceed with execution in that case).     */    suspend fun getCurrentState(): Any?    /**     * True if the device is already in the target state of [operation].     *     * When this returns true, [execute] skips the hardware call entirely     * (returns `Result.Success(Unit)` immediately). This avoids:     *  - Screen flicker (e.g., brightness set to current value).     *  - Battery drain from redundant hardware wake-ups.     *  - Race conditions from concurrent writes.     */    suspend fun isAlreadyInTargetState(operation: T): Boolean}// ──────────────────────────────────────────────────────────────────────────/** * Base class for handlers that don't support pre-state capture / restore. * * Used for fire-and-forget operations like clipboard copy, open app, open URL * — these have no "previous state" to restore. * * Subclasses override [execute] only; pre-state methods return null/false * by default. */abstract class StatelessSystemOperationHandler<T : SystemOperation> : SystemOperationHandler<T> {    override suspend fun capturePreState(operation: T): Any? = null    override suspend fun restorePreState(operation: T, preState: Any?) {        // No-op — stateless handler has nothing to restore.    }    override suspend fun getCurrentState(): Any? = null    override suspend fun isAlreadyInTargetState(operation: T): Boolean = false}// ──────────────────────────────────────────────────────────────────────────/** * Marker for handlers that support undo (most do — exceptions are clipboard, * open app, open URL, set alarm/timer which aren't reversible). * * The [com.roshan.persona.system.undo.PersistentUndoStack] only pushes * actions from handlers that implement this interface. * * ## Pre-state serialization (audit defect B fix) * * Each reversible handler MUST override [serializePreState] and * [deserializePreState] to round-trip its own pre-state data class. * The default impl only handles primitive types (Int / Long / Boolean / * String / Pair) — data-class pre-states fall through to `.toString()` * and become opaque Strings on deserialize, breaking undo silently. * * Implementations should produce compact JSON via [kotlinx.serialization] * or hand-rolled `String` concatenation — the format is opaque to the * stack (it stores the JSON string in Room as-is). */interface ReversibleHandler<T : SystemOperation> : SystemOperationHandler<T> {    /** Human-readable description of the operation for the undo UI. */    fun describeOperation(operation: T): String    /**     * Serialize a captured pre-state to a JSON string for Room persistence.     *     * Default impl handles primitives (Int/Long/Float/Double/Boolean/String/Pair)     * via [com.roshan.persona.system.undo.SystemOperationSerializer]. Handlers     * with data-class pre-states MUST override this to round-trip their type.     *     * @return JSON string, or null if [preState] is null.     */    fun serializePreState(preState: Any?): String? {        return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)    }    /**     * Deserialize a JSON string back to the pre-state value.     *     * Default impl handles primitives — handlers with data-class pre-states     * MUST override this to reconstruct their type.     *     * @return the pre-state value, or null if [json] is null.     */    fun deserializePreState(json: String?): Any? {        return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)    }}